package ovh.litapp.neurhome3.data.avatar

import android.app.Application
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

/**
 * Pins the resolver against `app/src/test/resources/dicebear/parity.json`.
 *
 * That fixture is generated by `tools/dicebear_parity_fixture.py`, which also regenerates the
 * SVG the reference implementation produces for the same seed: `python3
 * tools/dicebear_parity_fixture.py verify` diffs it against api.dicebear.com, and every
 * vendored style matches byte for byte. So this test is what keeps the on-device avatars
 * identical to the ones the same seed produces everywhere else.
 */
@RunWith(RobolectricTestRunner::class)
@Config(application = Application::class)
class DiceBearParityTest {

    private val application: Application = RuntimeEnvironment.getApplication()

    @Test
    fun everyStyleAndSeedResolvesLikeTheReferenceImplementation() {
        val fixture = fixture()
        val styles = fixture.styles.keys
        assertEquals(
            "the fixture must cover exactly the vendored styles",
            (DiceBearStyle.entries - DiceBearStyle.NONE).map { it.id }.toSet(),
            styles,
        )
        for ((styleId, seeds) in fixture.styles) {
            val style = DiceBearStyle.entries.first { it.id == styleId }
            val definition = requireNotNull(style.definition(application)) { "$styleId is not parseable" }
            assertEquals("the fixture's seeds for $styleId", fixture.seeds.toSet(), seeds.keys)
            for ((seed, expected) in seeds) {
                assertEquals(
                    "$styleId/$seed",
                    ResolvedStyleOptions(
                        components = expected.components.mapValues { (_, component) ->
                            ResolvedComponentOptions(
                                visible = component.visible,
                                variant = component.variant,
                                rotate = component.rotate,
                                translateX = component.translateX,
                                translateY = component.translateY,
                                scale = component.scale,
                            )
                        },
                        colors = expected.colors,
                    ),
                    AvatarStyleResolver(definition).resolveOptions(seed),
                )
            }
        }
    }

    /**
     * The values the live API returned for these two seeds, spelled out: they are the
     * end-to-end sanity check that the fixture above is the real thing rather than a
     * restatement of whatever the port happens to do.
     */
    @Test
    fun thePublishedApiValuesForIdenticonAndShadowsResolveIdentically() {
        val identicon = AvatarStyleResolver(
            requireNotNull(DiceBearStyle.IDENTICON.definition(application)),
        ).resolveOptions("Ada")
        // Rows are drawn top to bottom as row01..row05; the canvas references row05 first,
        // translated to the bottom.
        assertEquals(
            listOf("xxxxx", "xooox", "oxoxo", "xxxxx", "ooxoo"),
            (1..5).map { identicon.components.getValue("row0$it").variant },
        )
        assertEquals(listOf("#1499da"), identicon.colors["row"])

        val shadows = AvatarStyleResolver(
            requireNotNull(DiceBearStyle.SHADOWS.definition(application)),
        ).resolveOptions("Ada")
        assertEquals("wide", shadows.components.getValue("shoulders").variant)
        assertEquals("oval", shadows.components.getValue("heads").variant)
        // `tops` has probability 76, and this seed rolls above it.
        assertTrue(shadows.components.getValue("tops").variant == null)
        assertEquals(listOf("#dfe8ed"), shadows.colors["background"])
        assertEquals(listOf("#345945"), shadows.colors["ink"])
    }

    private fun fixture(): ParityFixture {
        val stream = requireNotNull(javaClass.getResourceAsStream("/dicebear/parity.json")) {
            "app/src/test/resources/dicebear/parity.json is missing"
        }
        // The fixture also records which script and styles version produced it.
        val json = Json { ignoreUnknownKeys = true }
        return stream.use { json.decodeFromString<ParityFixture>(it.readBytes().decodeToString()) }
    }
}

@Serializable
private data class ParityFixture(
    val seeds: List<String>,
    val styles: Map<String, Map<String, ParityStyle>>,
)

@Serializable
private data class ParityStyle(
    val components: Map<String, ParityComponent>,
    val colors: Map<String, List<String>>,
)

@Serializable
private data class ParityComponent(
    val visible: Boolean,
    val variant: String? = null,
    val rotate: Double,
    val translateX: Double,
    val translateY: Double,
    val scale: Double,
)
